    print(json.dumps({"r": None, "p": None}))
    raise SystemExit

f1['season_year'] = pd.to_numeric(f1['season_year'])
f1['british_constructor_points'] = pd.to_numeric(f1['british_constructor_points'])

def parse_year(x):
    s = str(x)
    if '/' in s:
        return int(s.split('/')[0])
    return int(float(s))

epl['season_year'] = epl['season_label'].map(parse_year)
epl['avg_home_goals'] = pd.to_numeric(epl['avg_home_goals'])

merged = pd.merge(
    f1[['season_year', 'british_constructor_points']],
    epl[['season_year', 'avg_home_goals']],
    on='season_year',
    how='inner'
).sort_values('season_year')

