    out = {"r": None, "p": None}
else:
    r, p = pearsonr(merged['british_constructor_points'].to_numpy(dtype=float), merged['avg_home_goals'].to_numpy(dtype=float))
    out = {"r": float(r), "p": float(p)}

print(json.dumps(out, separators=(',', ':')))

