    merged['constructor_win_rate'] = pd.to_numeric(merged['constructor_win_rate'], errors='coerce')
    merged['avg_total_goals_per_match'] = pd.to_numeric(merged['avg_total_goals_per_match'], errors='coerce')
    merged = merged.dropna()
    if len(merged) < 2:
        result = {"spearman_r": None}
    else:
        r, _ = spearmanr(merged['constructor_win_rate'].to_numpy(), merged['avg_total_goals_per_match'].to_numpy())
        result = {"spearman_r": None if pd.isna(r) else float(r)}

